mapper.select:
SELECT r.id AS id, r.vault_id AS vaultId, s.name AS vaultName, r.user_id AS userId, u.user_name AS userName, u.nick_name AS nickName, r.replica_id AS replicaId, r.device_id AS deviceId, r.client_info AS clientInfo, r.last_seen_at AS lastSeenAt, r.create_time AS boundAt FROM vault_replica r INNER JOIN vault_space s ON s.id = r.vault_id AND s.del_flag = '0' LEFT JOIN sys_user u ON u.user_id = r.user_id WHERE 1 = 1
AND r.vault_id = #{vaultId}
AND (u.user_name LIKE CONCAT('%', #{keyword}, '%') OR u.nick_name LIKE CONCAT('%', #{keyword}, '%') OR s.name LIKE CONCAT('%', #{keyword}, '%') OR r.client_info LIKE CONCAT('%', #{keyword}, '%') OR r.replica_id LIKE CONCAT('%', #{keyword}, '%'))
AND r.device_id LIKE CONCAT('%', #{deviceId}, '%')
AND r.last_seen_at < #{inactiveBefore}
ORDER BY r.last_seen_at DESC, r.id DESC

SELECT r.asset_id AS assetId, r.vault_id AS vaultId, s.name AS vaultName, s.user_id AS userId, u.user_name AS userName, u.nick_name AS nickName, r.sha256 AS sha256, MAX(r.size_bytes) AS sizeBytes, MAX(r.mime_type) AS mimeType, MAX(r.storage_key) AS storageKey, MAX(r.config_id) AS configId, MAX(fc.name) AS configName, MAX(r.backend) AS backend, MAX(bf.name) AS fileName, MIN(f.path) AS samplePath, (SELECT COUNT(*) FROM vault_asset_ref r2 WHERE r2.asset_id = r.asset_id AND r2.vault_id = r.vault_id) AS refCount, MIN(r.create_time) AS createTime FROM vault_asset_ref r INNER JOIN vault_space s ON s.id = r.vault_id AND s.del_flag = '0' LEFT JOIN sys_user u ON u.user_id = s.user_id LEFT JOIN vault_file f ON f.id = r.file_id AND f.deleted = 0 LEFT JOIN basics_file bf ON bf.id = r.asset_id LEFT JOIN basics_file_config fc ON fc.id = r.config_id WHERE 1 = 1
AND r.vault_id = #{vaultId}
AND (u.user_name LIKE CONCAT('%', #{keyword}, '%') OR u.nick_name LIKE CONCAT('%', #{keyword}, '%') OR s.name LIKE CONCAT('%', #{keyword}, '%') OR f.path LIKE CONCAT('%', #{keyword}, '%') OR bf.name LIKE CONCAT('%', #{keyword}, '%') OR r.sha256 LIKE CONCAT('%', #{keyword}, '%') OR r.mime_type LIKE CONCAT('%', #{keyword}, '%') OR r.storage_key LIKE CONCAT('%', #{keyword}, '%'))
AND LOWER(r.backend) = #{backend}
AND LOWER(r.mime_type) LIKE CONCAT(#{mimePrefix}, '%')
GROUP BY r.asset_id, r.vault_id, s.name, s.user_id, u.user_name, u.nick_name, r.sha256 ORDER BY createTime DESC, assetId DESC

SELECT COUNT(*)
FROM vault_file
WHERE deleted = 1 AND update_time < #{cutoff}
